import React, { useState, useEffect } from 'react';
import Card from '../components/Card';

// Imports de dados (vamos usá-los dinamicamente)
import deepData from '../data/deep-end.json';
import unfilteredData from '../data/unfiltered.json';
import labData from '../data/lab.json';

const Game = ({ modeId, onBack }) => {
  const [questions, setQuestions] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);
  
  // Estado para as cores dinâmicas
  const [themeColor, setThemeColor] = useState('#00F0FF'); // Default Ciano
  const [bgColor, setBgColor] = useState('bg-raw-onyx'); // Default Onyx

  // Mapeamento de Configurações de Modo (Cores e Dados)
  const modeConfigs = {
    deep: {
      data: deepData,
      color: '#00F0FF', // RAW. Cyan
      bg: 'bg-raw-onyx',
      glow: 'shadow-[0_0_15px_rgba(0,240,255,0.8)]'
    },
    unfiltered: {
      data: unfilteredData,
      color: '#FF3E3E', // RAW. Red
      bg: 'bg-[#0F0A0A]', // Um Onyx ligeiramente mais avermelhado para atmosfera
      glow: 'shadow-[0_0_15px_rgba(255,62,62,0.8)]'
    },
    lab: {
      data: labData,
      color: '#F2F2F2', // RAW. Bone
      bg: 'bg-black', // Totalmente preto para foco técnico
      glow: 'shadow-[0_0_15px_rgba(242,242,242,0.8)]'
    }
  };

  // 🛠️ 1. Carregar Configurações, Cores e Baralhar Perguntas
  useEffect(() => {
    // Garante que o modo existe, se não, usa deep como fallback
    const config = modeConfigs[modeId] || modeConfigs.deep;
    
    // Define as cores
    setThemeColor(config.color);
    setBgColor(config.bg);
    
    // Processa e baralha as perguntas
    const allQuestions = config.data.categories.flatMap(cat => 
      cat.questions.map(q => ({ 
        text: q, 
        category: cat.title,
        color: config.color // Passamos a cor para o cartão saber como se comportar
      }))
    );
    
    // Reseta o índice e baralha
    setCurrentIndex(0);
    setQuestions(allQuestions.sort(() => Math.random() - 0.5));
    
  }, [modeId]); // Roda sempre que o modo muda

  const nextQuestion = () => {
    if (isAnimating || questions.length === 0) return;
    setIsAnimating(true);
    
    setTimeout(() => {
      // Loop: volta ao início se chegar ao fim
      setCurrentIndex((prev) => (prev + 1) % questions.length);
      setIsAnimating(false);
    }, 300);
  };

  // Se não houver perguntas (modo inválido ou vazio), mostra um placeholder
  if (questions.length === 0) {
    return (
      <div className={`min-h-screen ${bgColor} flex flex-col items-center justify-center p-6 text-raw-bone`}>
        A carregar o laboratório...
      </div>
    );
  }

  // Configuração ativa para usar as classes de glow/bg
  const activeConfig = modeConfigs[modeId] || modeConfigs.deep;

  return (
    <div className={`min-h-screen ${bgColor} flex flex-col items-center justify-center p-6 overflow-hidden transition-colors duration-500`}>
      
      {/* 🛠️ 2. Botão de SAIR (Voltar para Home) - Canto Superior Esquerdo */}
      <button 
        onClick={onBack}
        className="fixed top-8 left-8 p-3 bg-raw-bone rounded-full text-raw-onyx font-bold text-xl hover:scale-110 transition-transform z-50 shadow-[0_4px_10px_rgba(0,0,0,0.3)]"
        aria-label="Sair do Jogo"
      >
        <span style={{ color: activeConfig.color }}>✕</span>
      </button>

      {/* 🛠️ HUD de Progresso / Incandescência Dinâmica */}
      <div className="fixed top-20 w-full max-w-md px-10 z-30 md:top-10">
        <div className="flex justify-between text-[10px] text-raw-bone/40 uppercase tracking-widest mb-2 font-archivo">
          <span>Início</span>
          <span>Fim</span>
        </div>
        <div className="h-1 bg-raw-bone/10 w-full">
          {/* A cor e o glow mudam com o modo */}
          <div 
            className={`h-full transition-all duration-500 ${activeConfig.glow}`}
            style={{ 
              width: `${((currentIndex + 1) / questions.length) * 100}%`,
              backgroundColor: activeConfig.color
            }}
          />
        </div>
        <div className="text-center mt-1 text-[10px] text-raw-bone/20 uppercase">
          Pergunta {currentIndex + 1} de {questions.length}
        </div>
      </div>

      {/* Área do Cartão (recebe a cor dinâmica) */}
      <div 
        onClick={nextQuestion}
        className={`cursor-pointer transition-all duration-300 transform ${
          isAnimating ? 'scale-95 opacity-0 rotate-3' : 'scale-100 opacity-100 rotate-0'
        } z-20`}
      >
        <Card 
          text={questions[currentIndex].text} 
          category={questions[currentIndex].category}
          color={questions[currentIndex].color} // Passamos a cor para o cartão
        />
      </div>

      {/* Controlos de Rodapé */}
      <div className="mt-16 flex flex-col items-center z-10">
        <button 
          onClick={nextQuestion}
          className="text-raw-bone font-archivo text-xs uppercase tracking-[0.4em] pb-2 transition-colors duration-300"
          style={{ borderBottom: `2px solid ${activeConfig.color}` }}
        >
          Toca para Próxima
        </button>
        
        <div className="mt-12 opacity-20 hover:opacity-100 transition-opacity">
           <a 
             href="https://github.com/16alves02" 
             target="_blank" 
             rel="noopener noreferrer"
             className="text-[10px] text-raw-bone uppercase font-inter tracking-widest hover:text-raw-cyan transition-colors"
            >
             Developer @16alves02
           </a>
        </div>
      </div>
    </div>
  );
};

export default Game;
